
const PMETA = [{"id": "l2", "cat": "logo", "tag": "Logo Design", "client": "Various Clients", "title": "Elegant Logo Collection I", "year": "2024", "tools": "Illustrator", "desc": "Luxury brand logos \u2014 photography studios, cocktail bars, beauty brands. Script and serif letterforms with clean negative space."}, {"id": "l3", "cat": "logo", "tag": "Logo Design", "client": "Various Clients", "title": "Monogram Logo Collection", "year": "2024", "tools": "Illustrator", "desc": "Premium monogram logomarks \u2014 geometric letterforms, badge-style seals, and ornamental initials in gold and navy."}, {"id": "l4", "cat": "logo", "tag": "Logo Design", "client": "Various Clients", "title": "Elegant Logo Collection II", "year": "2024", "tools": "Illustrator", "desc": "Ashley Corinne, D'Aurea Signature, Atelier Mica, Ashleigh Virtue \u2014 monogram scripts and clean serif wordmarks."}, {"id": "l5", "cat": "logo", "tag": "Logo Design", "client": "Various Clients", "title": "Logo Listing \u2014 Set 5", "year": "2024", "tools": "Illustrator", "desc": "Versatile portfolio set across brand categories from wellness to hospitality."}, {"id": "l6", "cat": "logo", "tag": "Logo Design", "client": "Various Clients", "title": "Logo Listing \u2014 Set 6", "year": "2024", "tools": "Illustrator", "desc": "Clean modern logomarks on geometric foundations \u2014 scalable and brand-clear across all use cases."}, {"id": "l7", "cat": "logo", "tag": "Logo Design", "client": "Various Clients", "title": "Logo Listing \u2014 Set 7", "year": "2024", "tools": "Illustrator", "desc": "Bold collection from abstract symbol marks to precise letterform logos, each crafted for instant brand recognition."}, {"id": "l8", "cat": "logo", "tag": "Logo Design", "client": "Various Clients", "title": "Logo Listing \u2014 Set 8", "year": "2024", "tools": "Illustrator", "desc": "Refined wordmarks, geometric icons, and complete brand mark systems across luxury, lifestyle, and corporate."}, {"id": "w2", "cat": "brand", "tag": "Brand Identity", "client": "Love II", "title": "Love II \u2014 Luxury Brand System", "year": "2024", "tools": "Illustrator", "desc": "Complete luxury brand identity \u2014 crown monogram deployed across packaging, cards, storefront signage, and dark/light environments."}, {"id": "ab4", "cat": "social", "tag": "Social Media", "client": "Bridge Power Batteries", "title": "Right Battery, Bright Home", "year": "2024", "tools": "Photoshop", "desc": "Bold diagonal composition for RB 3000 tubular battery. Split-scene design contrasting luxury interior with product on deep red."}, {"id": "ab5", "cat": "social", "tag": "Social Media", "client": "Bridge Power Batteries", "title": "Built for Power", "year": "2024", "tools": "Photoshop", "desc": "Cinematic cityscape backdrop \u2014 battery centre-stage with bold italic tagline. Designed to command attention in social feeds."}, {"id": "ab6", "cat": "social", "tag": "Social Media", "client": "Bridge Power Batteries", "title": "Smart Technology, Powerful Energy", "year": "2024", "tools": "Photoshop", "desc": "Split-diagonal layout with automotive imagery and lightning-strike effects emphasising power and energy."}, {"id": "ab7", "cat": "social", "tag": "Social Media", "client": "Bridge Power Batteries", "title": "Every Road. Every Journey.", "year": "2024", "tools": "Photoshop", "desc": "Truck campaign with cinematic night highway photography and feature icon bar communicating key specs."}, {"id": "ab8", "cat": "social", "tag": "Social Media", "client": "Bridge Power Batteries", "title": "Reliable Power for Every Moment", "year": "2024", "tools": "Photoshop", "desc": "Clean product lifestyle post \u2014 warm sunset orb, stone pedestal, and vertical feature icons for premium communication."}, {"id": "ab9", "cat": "social", "tag": "Social Media", "client": "Bridge Power Batteries", "title": "Always Ready to Power Your Needs", "year": "2024", "tools": "Photoshop", "desc": "RB 3000 powering TV, laptop, and home. Layered floating cards on bold red background with strong copy hierarchy."}, {"id": "ab10", "cat": "social", "tag": "Social Media", "client": "Bridge Power Batteries", "title": "Powerful Backup, Brighter Living", "year": "2024", "tools": "Photoshop", "desc": "Residential backup power campaign with clean architectural photography and diagonal panel composition."}, {"id": "wa3", "cat": "creative", "tag": "Creative Design", "client": "Personal Project", "title": "DUA \u2014 Editorial Typography Poster", "year": "2024", "tools": "Photoshop", "desc": "Bold typographic editorial \u2014 oversized letterforms as visual mask for a portrait. Deep maroon gradient with high-contrast white type."}, {"id": "wa1", "cat": "creative", "tag": "Creative Design", "client": "Personal Project", "title": "Artist Portrait \u2014 Geometric Layout", "year": "2024", "tools": "Photoshop", "desc": "Black and white editorial portrait with geometric three-panel grid overlay and clean serif display type at base."}];
const PIMGS = ["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"];
let extra=[], isOwner=false, imgData=null, af='all';

// LOADER
setTimeout(()=>document.getElementById('loader').classList.add('gone'),1300);

// TYPING
const roles=['Logo Designer','Brand Identity','Social Media Design','Creative Designer'];
let ri=0,ci=0,td=false,rel=document.getElementById('role');
function type(){const c=roles[ri];if(!td){rel.textContent=c.slice(0,++ci);if(ci===c.length){td=true;setTimeout(type,2000);return;}}else{rel.textContent=c.slice(0,--ci);if(ci===0){td=false;ri=(ri+1)%roles.length;}}setTimeout(type,td?50:90);}
setTimeout(type,1600);

// CURSOR
if(!('ontouchstart' in window)){
  const cd=document.querySelector('.cd'),cr=document.querySelector('.cr');
  let mx=0,my=0,rx=0,ry=0;
  document.addEventListener('mousemove',e=>{mx=e.clientX;my=e.clientY;cd.style.left=mx+'px';cd.style.top=my+'px';});
  (function a(){rx+=(mx-rx)*.1;ry+=(my-ry)*.1;cr.style.left=rx+'px';cr.style.top=ry+'px';requestAnimationFrame(a);})();
  document.querySelectorAll('a,button,.pc,.cc,.srow,.sk,.ec').forEach(el=>{el.addEventListener('mouseenter',()=>document.body.classList.add('hov'));el.addEventListener('mouseleave',()=>document.body.classList.remove('hov'));});
}else{document.getElementById('cur').style.display='none';}

// NAV SCROLL BTT
window.addEventListener('scroll',()=>{
  document.getElementById('nav').classList.toggle('sc',scrollY>50);
  document.getElementById('prog').style.width=(scrollY/(document.body.scrollHeight-innerHeight)*100)+'%';
  document.getElementById('btt').classList.toggle('show',scrollY>500);
});
function tmenu(){document.getElementById('ham').classList.toggle('o');document.getElementById('mm').classList.toggle('o');}

// REVEAL
const io=new IntersectionObserver(es=>{es.forEach(e=>{if(!e.isIntersecting)return;e.target.classList.add('vis');io.unobserve(e.target);});},{threshold:.1});
document.querySelectorAll('.rv,.rl,.rr').forEach(el=>io.observe(el));
const skio=new IntersectionObserver(([e])=>{if(!e.isIntersecting)return;e.target.querySelectorAll('.sk').forEach((s,i)=>{const b=s.querySelector('.sk-fill');if(b)setTimeout(()=>b.style.width=s.dataset.p+'%',130+i*80);});skio.unobserve(e.target);},{threshold:.1});
const sg=document.getElementById('skg');if(sg)skio.observe(sg);

// FILTER (seed cards)
document.querySelectorAll('.fb').forEach(btn=>{
  btn.addEventListener('click',()=>{
    document.querySelectorAll('.fb').forEach(b=>b.classList.remove('on'));
    btn.classList.add('on');af=btn.dataset.f;
    filterGrid();
  });
});
function filterGrid(){
  document.querySelectorAll('.pgrid > .pc[data-cat]').forEach(el=>{
    el.style.display=(af==='all'||el.dataset.cat===af)?'':'none';
  });
  extraRender();
}

// VIEW MODAL (seed)
function openV(idx){
  const allP=[...PMETA,...extra];
  const allI=[...PIMGS,...extra.map(p=>p.img)];
  const p=allP[idx], img=allI[idx];
  document.getElementById('vm-img').src=img;
  document.getElementById('vm-tag').textContent=p.tag;
  document.getElementById('vm-cl').textContent=p.client||'—';
  document.getElementById('vm-yr').textContent=p.year||'—';
  document.getElementById('vm-tl').textContent=p.tools||'—';
  document.getElementById('vm-ti').textContent=p.title;
  document.getElementById('vm-de').textContent=p.desc||'';
  document.getElementById('vmod').classList.add('open');
  document.body.style.overflow='hidden';
}
function closeV(){document.getElementById('vmod').classList.remove('open');document.body.style.overflow='';}

// ADD MODAL
function openAdd(){document.getElementById('amod').classList.add('open');document.body.style.overflow='hidden';}
function closeAdd(){document.getElementById('amod').classList.remove('open');document.body.style.overflow='';resetF();}
function resetF(){
  ['ft','fcl','fd','ftl'].forEach(id=>{const e=document.getElementById(id);if(e)e.value='';});
  document.getElementById('fy').value='2024';
  document.getElementById('fc').value='logo';
  imgData=null;
  document.getElementById('upv').style.display='none';
  document.getElementById('uph').style.display='flex';
  document.getElementById('upld').classList.remove('hi');
  document.getElementById('savetxt').textContent='Save Project';
  document.getElementById('savebtn').disabled=false;
}
function onImg(e){
  const file=e.target.files[0];if(!file)return;
  if(file.size>8*1024*1024){alert('Max 8MB please.');return;}
  const r=new FileReader();
  r.onload=ev=>{
    imgData=ev.target.result;
    const v=document.getElementById('upv');v.src=imgData;v.style.display='block';
    document.getElementById('uph').style.display='none';
    document.getElementById('upld').classList.add('hi');
  };r.readAsDataURL(file);
}
function toast(msg){
  const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');
  setTimeout(()=>t.classList.remove('show'),2200);
}

const CAT_CLR={
  logo:['rgba(108,78,242,.15)','#a78bfa'],
  brand:['rgba(240,100,150,.15)','#f472b6'],
  social:['rgba(16,185,129,.15)','#34d399'],
  creative:['rgba(245,158,11,.15)','#fbbf24'],
};
const CAT_LABELS={logo:'Logo Design',brand:'Branding',social:'Social Media',creative:'Creative Design'};

function extraRender(){
  // Remove old extra cards
  document.querySelectorAll('.pc.extra').forEach(el=>el.remove());
  const grid=document.getElementById('pgrid');
  const base=PMETA.length;
  extra.forEach((p,i)=>{
    if(af!=='all'&&p.cat!==af)return;
    const [bg,col]=CAT_CLR[p.cat]||CAT_CLR.logo;
    const num=String(base+i+1).padStart(2,'0');
    const art=document.createElement('article');
    art.className='pc extra';art.dataset.cat=p.cat;
    art.innerHTML=`
      <div class="pc-img">
        <img src="${p.img}" alt="${p.title}" loading="lazy">
        <div class="pc-ov"><button class="pc-vbtn" onclick="openV(${base+i})">↗ Open</button></div>
        <span class="pc-badge" style="background:${bg};color:${col}">${p.tag}</span>
        <button class="del-btn" onclick="event.stopPropagation();delP(${i})">✕</button>
      </div>
      <div class="pc-foot">
        <span class="pc-num">${num}</span>
        <div class="pc-txt"><div class="pc-title">${p.title}</div><div class="pc-sub">${[p.client,p.tools].filter(Boolean).join(' · ')}</div></div>
        <div class="pc-arr" onclick="openV(${base+i})">↗</div>
      </div>`;
    grid.appendChild(art);
  });
  // Update counts
  const n=PMETA.length+extra.length;
  document.getElementById('hcnt').textContent=n+'+';
  document.getElementById('acnt').textContent=n+'+';
}

function saveP(){
  const title=document.getElementById('ft').value.trim();
  if(!title){alert('Please enter a project title.');return;}
  if(!imgData){alert('Please upload a project image.');return;}
  const cat=document.getElementById('fc').value;
  extra.unshift({
    id:'p_'+Date.now(),cat,
    tag:CAT_LABELS[cat]||cat,
    title,
    client:document.getElementById('fcl').value.trim(),
    year:document.getElementById('fy').value.trim()||'2024',
    tools:document.getElementById('ftl').value.trim(),
    desc:document.getElementById('fd').value.trim(),
    img:imgData,
  });
  // Save to localStorage
  try{
    const save=extra.map(p=>p);
    localStorage.setItem('msk_projects',JSON.stringify(save));
  }catch(e){}
  extraRender();closeAdd();toast('Project saved ✓');
}

function delP(i){
  if(!confirm('Delete this project?'))return;
  extra.splice(i,1);
  try{localStorage.setItem('msk_projects',JSON.stringify(extra));}catch(e){}
  extraRender();toast('Deleted ✓');
}

// SEED card view modal links
document.querySelectorAll('.pc:not(.extra) .pc-vbtn,.pc:not(.extra) .pc-arr').forEach(el=>{
  const idx=parseInt(el.closest('.pc').dataset.idx);
  el.onclick=()=>openV(idx);
});
// Seed delete buttons
document.querySelectorAll('.pc:not(.extra) .del-btn').forEach(el=>{
  el.addEventListener('click',e=>{
    e.stopPropagation();
    toast('Default projects cannot be deleted.');
  });
});

document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeV();closeAdd();}});

// FORM
function doForm(e){
  e.preventDefault();const b=document.getElementById('fsub');
  b.textContent='Sending...';b.disabled=true;
  setTimeout(()=>{b.textContent='Sent ✓';b.style.background='#16a34a';
    setTimeout(()=>{b.textContent='Send Message →';b.style.background='';b.disabled=false;e.target.reset();},2500);
  },900);
}

// INIT: load saved extra projects
(function init(){
  try{
    const saved=JSON.parse(localStorage.getItem('msk_projects')||'[]');
    if(saved.length){extra=saved;extraRender();}
  }catch(e){}
  // Show add button (always visible — Saad uses this on his device)
  document.getElementById('addbtn').classList.add('show');
  document.body.classList.add('owner');
})();
